package com.ledgerly.net

import kotlinx.coroutines.runBlocking
import okhttp3.Authenticator
import okhttp3.Request
import okhttp3.Response
import okhttp3.Route

class TokenRefreshAuthenticator(private val sessionStore: SessionStore) : Authenticator {
    override fun authenticate(route: Route?, response: Response): Request? {
        if (response.priorResponse != null) return null
        // OkHttp calls authenticate() synchronously on its own worker thread and needs the
        // new request as a return value, so we bridge to the suspend refresh here.
        val fresh = runBlocking { sessionStore.refreshAccessToken() } ?: return null
        return response.request.newBuilder().header("Authorization", "Bearer $fresh").build()
    }
}

