package com.quillhq.routes

import io.ktor.http.HttpStatusCode
import io.ktor.server.application.call
import io.ktor.server.response.respond
import io.ktor.server.routing.Route
import io.ktor.server.routing.get

fun Route.articleRoutes(articles: ArticleService) {
    get("/articles/{slug}") {
        val slug = call.parameters["slug"] ?: return@get call.respond(HttpStatusCode.BadRequest)
        val article = articles.findPublished(slug)
            ?: return@get call.respond(HttpStatusCode.NotFound)
        call.respond(ArticleResponse.from(article))
    }

    get("/articles") {
        val page = call.request.queryParameters["page"]?.toIntOrNull()?.coerceAtLeast(0) ?: 0
        call.respond(articles.listPublished(page = page, pageSize = 20).map(ArticleSummary::from))
    }
}

