package com.ledgerly.model

import java.text.NumberFormat
import java.util.Currency
import java.util.Locale

@JvmInline
value class Money(val cents: Long) {
    operator fun plus(other: Money) = Money(cents + other.cents)
    operator fun minus(other: Money) = Money(cents - other.cents)

    fun format(currency: Currency, locale: Locale = Locale.getDefault()): String =
        NumberFormat.getCurrencyInstance(locale).apply { this.currency = currency }.format(cents / 100.0)

    companion object {
        val ZERO = Money(0)
        fun sum(values: Iterable<Money>) = values.fold(ZERO, Money::plus)
    }
}

